package main

import (
	"bufio"
	"fmt"
	"os"
)

type Scanner struct {
	reader *bufio.Reader
	buffer []string
}

func NewScanner(reader *bufio.Reader) *Scanner {
	return &Scanner{
		reader: reader,
		buffer: []string{},
	}
}

func (s *Scanner) token() string {
	for {
		if len(s.buffer) > 0 {
			token := s.buffer[len(s.buffer)-1]
			s.buffer = s.buffer[:len(s.buffer)-1]
			return token
		}
		input, err := s.reader.ReadString('\n')
		if err != nil {
			panic("Failed read")
		}
		fields := []string{}
		start := -1
		for i, c := range input {
			if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
				if start != -1 {
					fields = append(fields, input[start:i])
					start = -1
				}
			} else if start == -1 {
				start = i
			}
		}
		if start != -1 {
			fields = append(fields, input[start:len(input)])
		}
		for i := len(fields) - 1; i >= 0; i-- {
			s.buffer = append(s.buffer, fields[i])
		}
	}
}

func isPrime(n int64) bool {
	var d int64 = 2
	for d*d <= n {
		if n%d == 0 {
			return false
		}
		d++
	}
	return true
}

func solve(scan *Scanner, out *bufio.Writer) {
	var t uint32
	fmt.Sscan(scan.token(), &t)
	for i := uint32(0); i < t; i++ {
		var a, b int64
		fmt.Sscan(scan.token(), &a)
		fmt.Sscan(scan.token(), &b)
		if a-b == 1 && isPrime(a+b) {
			fmt.Fprintln(out, "YES")
		} else {
			fmt.Fprintln(out, "NO")
		}
	}
}

